prts.feedbackvariables:
evals:if is(length(ans2)=length(ans2[1])) then eigenvalues(ans2)[1] else [0];
ev2: eigenvectors(ans2);
k2: length(ev2[1][1]);
dots: flatten(makelist(makelist(makelist(makelist(ev2[2][ii][aa] . conjugate(ev2[2][jj][bb]), bb, 1, length(ev2[2][jj])), aa, 1, length(ev2[2][ii])), jj, ii+1, k2), ii, 1, k2));
orthOK: is(ratsimp(rectform(apply("+", map(lambda([z], z*conjugate(z)), dots)))) = 0);
checkAns: is(not(is(ans2 . conjugate(transpose(ans2)) = conjugate(transpose(ans2)). ans2 ))  and is(apply("+",map(length,eigenvectors(ans2)[2])) < length(ans2)) and orthOK);
